    s.GenerateTriangleListAndStrip(empty, out, strip);
    ok = ok && s.Calls == 1 && out.size() == 0 && strip.V.empty();
    if (!ok) { std::printf("00f3f3a0_TEST FAIL\n"); return 1; }
